Method.Implementation:
	set sysText = ""
 	if (err.%IsA("%Exception.SystemException") )
 	{
	 	set sysText = " SystemException: " _err.AsSystemError()_ "; "	 
 	}
 	If $GET(%objlasterror) '="" 
 	{
 		set sysText = sysText _ "ErrorText: " _ $System.Status.GetErrorText(%objlasterror) _ "; "	 
 	}


 	$$$LOGERROR("Exception in calling " _ method _ sysText _ ";$ZERROR: " _ $ZERROR _ ";ErrName: " _ $ZCVT(err.Name,"O","HTML")_ "; ErrData: " _ err.Data _ "; ErrCode:" _ err.Code _ "ErrLocation:" _ err.Location)	    	    	    

	set stat = $$$ERROR("Exception in " _ method _ "; " _ err.Data _ ", " _ sysText  _ ";$ZERROR: " _ $ZERROR _ ";ErrName: " _ $ZCVT(err.Name,"O","HTML")_ "; ErrData: " _ err.Data _ "; ErrCode:" _ err.Code _ "ErrLocation:" _ err.Location)	    	    	    

	     set errText = $SYSTEM.Status.GetOneErrorText(stat)
	     $$$TRACE("CDR Base Operation: ExceptionHandler: "_errText)
	     if errText["RESEND"{
		   Set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError(..%ConfigName,errText)
	     }Elseif errText["DATAERROR"{
		   Set status = ##class(IHC.ITF.ITFCOMMON.Utility).FailMsgError(..%ConfigName,errText)
	     }Elseif errText["SHUTDOWN"{
		   Set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError(..%ConfigName,errText)
	     }Elseif ( ((errText["CONNECTIONERROR")) || (errText'["DATAERROR")){
		    Try {
		    	do ..OnTearDown()
	    	}catch{}
	    	$$$TRACE("Reconnect to Gateway # " _ ..RetryCount _", MAX: " _ ..MaxRetryCount)
	    	// Connect to Gateway
            Set tSC = ..GetConnection(.tGateway, ..ConnectTimeout+10)
			If $$$ISOK(tSC) {
				set tSC = ..OnInit()
				If ( ($$$ISOK(tSC)) && (..RetryCount < ..MaxRetryCount) ) {
	    			Set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError(..%ConfigName,"Re connected to Gateway and Tuxedo")	
				}
				else
				{
					Set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError(..%ConfigName, "Connect to Tuxedo service stat: " _ tSC _ ", RetryCount: " _ ..RetryCount _", Max try: " _ ..MaxRetryCount)
				}
			}
			Else
			{		
				Set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError(..%ConfigName, "Could not reconnect to Gateway: " _ errText)
			}
	    }Else{
		    Set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError(..%ConfigName,errText)
	    }	    
	 $$$TRACE("ExceptionHandler return status: " _ status)
	 return status

$$$TRACE(" $$$$$ Inside OnTearDown() method...")
set tSC = $$$OK

try {		
	if $IsObject(..objCdrTuxService) {
		$$$TRACE("Disconnecting from CDR Tuxedo service...")
		do ..objCdrTuxService.shutdownTuxService()			
		set ..objCdrTuxService = $$$NULLOREF
		$$$TRACE("Disconnected - CDR Tuxedo service...")
	}
} catch {
	set tSC = $$$EnsSystemError
}
set tSC = ##super()
$$$TRACE("OnTearDown, status: " _ tSC)
quit tSC

     $$$TRACE("Last Recorded Time: "_..lastRecTime)
	 if (..lastRecTime '= "" )
	 {
		SET dateint2=$HOROLOG _ ".00"
	    $$$TRACE("Current Time: "_dateint2)

	 	set diff = $SYSTEM.SQL.DATEDIFF("hh", ..lastRecTime, dateint2)
	 	$$$TRACE("Idle time: "_diff)
	 	if (diff > ..MAXIDLETIME)
   		 {
	   		 $$$TRACE("Reconnect because the connection is older than " _ ..MAXIDLETIME_" hours.")
	   		 do ..CloseConnection()
	   		 quit $$$ERROR("Connection to Gateway is stale. Reconnect...")
   		 }
	 }
	 set ..lastRecTime = $HOROLOG _ ".00"
    If ( ($IsObject(..JavaGateway)) && ($IsObject(..objCdrTuxService)) )
	{
			$$$TRACE("Valid Object: " _ ..objCdrTuxService)
			quit $$$OK
	}
    elseif (' $IsObject(..JavaGateway))
    {
	    set ..objCdrTuxService = $$$NULLOREF 
	    quit $$$ERROR("Connection to Gateway is broken. " _ tSC)
    }
    else
    {
	    set ..objCdrTuxService = $$$NULLOREF 
	    quit $$$ERROR("Invalid object: objCdrTuxService")
    }
